  const [first, second, third] = args;
  if (typeof first === 'string' || Array.isArray(first)) {
    const rest = third ?? {};
    return { ...rest, optionStrings: first, dest: second ?? rest.dest };
  }
  return first ?? {};
}

export class Action {
  constructor(...args) {
    const opts = normalizeOptions(args);
    const optionStrings = opts.optionStrings ?? opts.option_strings ?? [];

    // '--a' alone is accepted as shorthand for ['--a'].
    this.optionStrings = typeof optionStrings === 'string' ? [optionStrings] : [...optionStrings];
    this.dest = opts.dest ?? null;
    this.nargs = opts.nargs ?? null; // Python None => "exactly one value"
    this.constValue = opts.constValue ?? opts.const ?? null;
    this.defaultValue = opts.defaultValue ?? opts.default ?? null;
    this.type = opts.type ?? null;
    this.choices = opts.choices ?? null;
    this.required = opts.required ?? false;
    this.help = opts.help ?? null;
    this.metavar = opts.metavar ?? null;
  }

  // CPython: Action.__call__ raises NotImplementedError('.__call__() not defined').
  call(parser, namespace, values, optionString) {
    throw new Error('.call() not defined');
  }
