 * `argument NAME: <message>` errors.
 *   optionals  -> all option strings joined with '/'  ('-h/--help')
 *   otherwise  -> metavar, else dest, else null
 * SUPPRESS placeholders count as "unset", exactly as in CPython.
 */
export function getActionName(action) {
  if (action == null) {
    return null;
