// ArgumentParser -- a port of the CPython 3.12 `argparse.ArgumentParser`
// scanning machinery: `add_argument`, `parse_known_args`, `_parse_known_args`,
// `_parse_optional`, `_get_option_tuples`, `_match_argument`, `_get_values` and
// `error`/`exit`. Layout and wrapping live in formatter.mjs; this module only
// decides *what* each token means and *when* each action fires.

import { getArgv, getProgName, writeStdout, writeStderr, exit, getTerminalColumns } from '../py/sys.mjs';
import { PyValueError, PyTypeError } from '../py/errors.mjs';
import { reprStr, pyStr } from '../py/repr.mjs';
import { Action, StoreAction, HelpAction, SUPPRESS } from './actions.mjs';
import { ArgumentError, ArgumentTypeError, getActionName } from './errors.mjs';
import { formatUsage, formatHelp } from './formatter.mjs';

/**
 * CPython `_ActionsContainer._negative_number_matcher`:
 * `re.compile(r'^-\d+$|^-\d*\.\d+$')`. Two Python-isms are reproduced here:
 *   * `\d` in a `str` pattern is Unicode-aware, hence `\p{Nd}` (so `-٥` is a
 *     number and therefore a positional, not an unknown option);
 *   * Python's `$` also matches immediately before a *trailing newline*, hence
 *     the `\n?` (verified: `--b $'-5\n'` is accepted as --b's value).
 */
const NEGATIVE_NUMBER_MATCHER = /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

/** CPython registers this under ('type', None): the default `type=` callable. */
function identity(string) {
  return string;
}

/** CPython's ('action', name) registry, reduced to the actions this port ships. */
const ACTION_CLASSES = new Map([
  ['store', StoreAction],
  ['help', HelpAction],
]);

function resolveActionClass(name) {
  if (name === undefined || name === null) return StoreAction; // registry entry for None
  if (typeof name === 'function') return name; // an Action subclass passed directly
  const cls = ACTION_CLASSES.get(name);
  if (cls === undefined) throw new PyValueError(`unknown action ${reprStr(String(name))}`);
  return cls;
}

/** Python `repr()` over the value kinds a `choices=` list can hold. */
function reprValue(value) {
  return typeof value === 'string' ? reprStr(value) : pyStr(value);
}

/** Python `hasattr(namespace, dest)` for a namespace modelled as a plain object. */
function hasDest(namespace, dest) {
  return Object.prototype.hasOwnProperty.call(namespace, dest);
}

/**
 * CPython `HelpFormatter._get_nargs_pattern`. The parser matches token
 * *classifications* -- 'A' (plain argument), 'O' (option) and '-' (the `--`
 * separator) -- against a regex built from the action's nargs, which is how
 * "does this option have a value after it?" is decided.
 */
function getNargsPattern(action) {
  const { nargs } = action;
  let pattern;
  if (nargs === null || nargs === undefined) pattern = '(-*A-*)'; // exactly one
  else if (nargs === '?') pattern = '(-*A?-*)';
  else if (nargs === '*') pattern = '(-*[A-]*)';
  else if (nargs === '+') pattern = '(-*A[A-]*)';
  else pattern = `(-*${Array.from({ length: nargs }, () => 'A').join('-*')}-*)`;

  // For optionals, '--' may not appear among the consumed tokens: CPython drops
  // every '-' from the pattern, so nargs=0 collapses to '()' and nargs=None to
  // '(A)'. That is why `--a --` reports "expected one argument".
  if (action.optionStrings.length > 0) {
    pattern = pattern.replaceAll('-*', '').replaceAll('-', '');
  }
  return pattern;
}

/** CPython's `nargs_errors` table in `_match_argument`. */
function nargsErrorMessage(nargs) {
  if (nargs === null || nargs === undefined) return 'expected one argument';
  if (nargs === '?') return 'expected at most one argument';
  if (nargs === '+') return 'expected at least one argument';
  return `expected ${nargs} argument${nargs === 1 ? '' : 's'}`;
}

export class ArgumentParser {
  constructor(options = {}) {
    // CPython: prog = os.path.basename(sys.argv[0]).
    this.prog = options.prog ?? getProgName();
    this.prefixChars = options.prefixChars ?? '-';
    this.exitOnError = options.exitOnError ?? true;

    this._actions = [];
    // Insertion-ordered, like CPython's `_option_string_actions` dict; the order
    // decides how prefix matches are listed in an "ambiguous option" message.
    this._optionStringActions = new Map();
    this._hasNegativeNumberOptionals = false;

    // The two default containers of an ArgumentParser, in display order.
    this._positionalsGroup = { title: 'positional arguments', actions: [] };
    this._optionalsGroup = { title: 'options', actions: [] };
    this._actionGroups = [this._positionalsGroup, this._optionalsGroup];

    // CPython adds -h/--help before any user argument when add_help is true.
    if (options.addHelp ?? true) {
      const p = this.prefixChars[0];
      this.addArgument([`${p}h`, `${p}${p}help`], {
        action: 'help',
        default: SUPPRESS,
        help: 'show this help message and exit',
      });
    }
  }

  /* ------------------------------------------------------------ building --- */

  /**
   * CPython `_ActionsContainer.add_argument`. `names` is one option string or a
   * list of them ('-h', '--help'); a single name that does not start with a
   * prefix char declares a positional instead.
   */
  addArgument(names, options = {}) {
    const nameList = typeof names === 'string' ? [names] : [...names];
    const kwargs = { ...options };
    const isPositional = nameList.length === 1 && !this.prefixChars.includes(nameList[0][0]);

    let optionStrings;
    let dest;
    if (isPositional) {
      // CPython `_get_positional_kwargs`: a positional is required unless its
      // nargs makes it skippable.
      optionStrings = [];
      [dest] = nameList;
      kwargs.required = !['?', '*'].includes(kwargs.nargs ?? null) || kwargs.nargs === '*'
        ? kwargs.nargs !== '?' && (kwargs.nargs !== '*' || kwargs.default === undefined)
        : false;
    } else {
      // CPython `_get_optional_kwargs`: dest comes from the first long option
      // ('--foo-bar' -> 'foo_bar'), falling back to the first short one.
      optionStrings = nameList;
      for (const optionString of optionStrings) {
        if (!this.prefixChars.includes(optionString[0])) {
          throw new PyValueError(
            `invalid option string ${reprStr(optionString)}: must start with a character `
            + `${reprStr(this.prefixChars)}`,
          );
        }
      }
      dest = kwargs.dest ?? null;
      if (dest === null) {
        const long = optionStrings.find((s) => s.length > 1 && this.prefixChars.includes(s[1]));
        let stripped = long ?? optionStrings[0];
        while (stripped.length > 0 && this.prefixChars.includes(stripped[0])) {
          stripped = stripped.slice(1);
        }
        if (stripped === '') {
          throw new PyValueError(`dest= is required for options like ${reprStr(optionStrings[0])}`);
        }
        dest = stripped.replaceAll('-', '_');
      }
    }

    const actionClass = resolveActionClass(kwargs.action);
    delete kwargs.action;
    delete kwargs.dest;
    // ('type', None) resolves to `identity` in CPython's registry.
    const action = new actionClass({ ...kwargs, optionStrings, dest, type: kwargs.type ?? identity });

    // CPython computes the default metavar lazily in the HelpFormatter
    // (`_get_default_metavar_for_optional` -> dest.upper(), positional -> dest).
    // Materialising it here keeps the formatter a pure layout function. nargs=0
    // actions never show a metavar, so -h stays `[-h]`.
    if (action.metavar === null && action.nargs !== 0) {
      action.metavar = optionStrings.length > 0 ? dest.toUpperCase() : dest;
    }

    return this._addAction(action);
  }

  /** CPython `_ActionsContainer._add_action` plus `_check_conflict`. */
  _addAction(action) {
    for (const optionString of action.optionStrings) {
      if (this._optionStringActions.has(optionString)) {
        throw new ArgumentError(action, `conflicting option string: ${optionString}`);
      }
    }
    this._actions.push(action);
    for (const optionString of action.optionStrings) {
      this._optionStringActions.set(optionString, action);
      // Remembering whether any option *looks* like a negative number decides
      // whether '-3' is read as a value or as an unknown option.
      if (NEGATIVE_NUMBER_MATCHER.test(optionString)) this._hasNegativeNumberOptionals = true;
    }
    const group = action.optionStrings.length > 0 ? this._optionalsGroup : this._positionalsGroup;
    group.actions.push(action);
    return action;
  }

  /* ------------------------------------------------------------- parsing --- */

  /** CPython `parse_args`: parse, then refuse to ignore leftover tokens. */
  parseArgs(args = null) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** CPython `parse_known_args`: seed defaults, scan, convert ArgumentError to error(). */
  parseKnownArgs(args = null) {
    const argStrings = args === null || args === undefined ? getArgv() : [...args];

    // The namespace is a plain object keyed by dest; a SUPPRESS default (as on
    // -h/--help) means "never put this dest in the namespace at all".
    const namespace = {};
    for (const action of this._actions) {
      if (action.dest !== SUPPRESS && !hasDest(namespace, action.dest)
          && action.defaultValue !== SUPPRESS) {
        namespace[action.dest] = action.defaultValue;
      }
    }

    if (!this.exitOnError) {
      return this._parseKnownArgs(argStrings, namespace);
    }
    try {
      return this._parseKnownArgs(argStrings, namespace);
    } catch (err) {
      // CPython: `except ArgumentError: self.error(str(err))` -- the action name
      // prefix is already baked into the message by ArgumentError itself.
      if (err instanceof ArgumentError) return this.error(err.message);
      throw err;
    }
  }

  /** CPython `_parse_known_args`: the left-to-right scan itself. */
  _parseKnownArgs(argStrings, namespace) {
    // -- Pass 1: classify every token. 'O' = option, 'A' = argument, '-' = the
    // `--` separator. Everything after the first `--` is forced to 'A'; `--`
    // itself stays in the token list and is only dropped later, by a positional
    // action consuming it (_get_values).
    const optionStringIndices = new Map();
    const patternParts = [];
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (argString === '--') {
        patternParts.push('-');
        for (let j = i + 1; j < argStrings.length; j += 1) patternParts.push('A');
        break;
      }
      const optionTuple = this._parseOptional(argString);
      if (optionTuple === null) {
        patternParts.push('A');
      } else {
        optionStringIndices.set(i, optionTuple);
        patternParts.push('O');
      }
    }
    const argStringsPattern = patternParts.join('');

    const seenActions = new Set();
    const extras = [];
    let positionals = this._actions.filter((action) => action.optionStrings.length === 0);

    // Convert an action's raw tokens and fire it. Conversion happening *here*,
    // mid-scan, is why `--a abc --b` reports the invalid int rather than --b's
    // missing value.
    const takeAction = (action, argumentStrings, optionString) => {
      seenActions.add(action);
      const argumentValues = this._getValues(action, argumentStrings);
      if (argumentValues !== SUPPRESS) {
        action.call(this, namespace, argumentValues, optionString);
      }
    };

    // CPython `consume_optional`.
    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
      const actionTuples = [];
      let stop;

      // Loops so that a single-dash cluster (`-hx`) can yield several actions.
      for (;;) {
        if (action === null) {
          // Unknown option: keep the token verbatim for the caller to report.
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this._matchArgument(action, 'A');

          if (argCount === 0 && sep !== '=' && !this.prefixChars.includes(optionString[1])
              && explicitArg !== '') {
            // Single-dash option that takes no argument: run it, then re-read
            // the tail as further short options ('-hx' -> '-h' then '-x').
            // `sep !== '='` is what keeps '-h=x' out of this branch.
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this._optionStringActions.has(optionString)) {
              action = this._optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              // The re-split produced an unknown option; the actions collected
              // so far still run (this is why '-hx' prints help).
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            // e.g. '--help=x': a zero-argument long option given a value.
            throw new ArgumentError(action, `ignored explicit argument ${reprStr(explicitArg)}`);
          }
        } else {
          // No '=' argument: take the following tokens, but only as many as the
          // action's nargs pattern matches against their classifications.
          const start = startIndex + 1;
          const argCount = this._matchArgument(action, argStringsPattern.slice(start));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [act, values, optStr] of actionTuples) takeAction(act, values, optStr);
      return stop;
    };

    // CPython `consume_positionals`: greedily hand tokens to the positionals
    // that are still unfilled. With no positional actions this is a no-op that
    // returns startIndex unchanged, which is what leaves `--` in the leftovers.
    const consumePositionals = (startIndex) => {
      const argCounts = this._matchArgumentsPartial(positionals, argStringsPattern.slice(startIndex));
      let index = startIndex;
      for (let k = 0; k < argCounts.length; k += 1) {
        const args = argStrings.slice(index, index + argCounts[k]);
        index += argCounts[k];
        takeAction(positionals[k], args, null);
      }
      positionals = positionals.slice(argCounts.length);
      return index;
    };

    // -- Pass 2: alternate positionals and optionals until past the last option.
    const indices = [...optionStringIndices.keys()];
    const maxOptionStringIndex = indices.length > 0 ? Math.max(...indices) : -1;
    let startIndex = 0;
    while (startIndex <= maxOptionStringIndex) {
      const nextOptionStringIndex = Math.min(...indices.filter((i) => i >= startIndex));
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
        if (startIndex !== nextOptionStringIndex) {
          extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
          startIndex = nextOptionStringIndex;
        }
      }
      startIndex = consumeOptional(startIndex);
    }
    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    // -- Required actions. This runs before the caller's unrecognized-arguments
    // check, so a missing --a beats a stray token; -h has already exited by now.
    const requiredActions = [];
    for (const action of this._actions) {
      if (seenActions.has(action)) continue;
      if (action.required) {
        requiredActions.push(getActionName(action));
      } else if (typeof action.defaultValue === 'string' && hasDest(namespace, action.dest)
                 && namespace[action.dest] === action.defaultValue) {
        // CPython converts a string default only now, so `type=` is never called
        // twice and never called at all when the argument was supplied.
        namespace[action.dest] = this._getValue(action, action.defaultValue);
      }
    }
    if (requiredActions.length > 0) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * CPython `_parse_optional`. Returns null when the token is a positional, or
   * the 4-tuple [action, optionString, sep, explicitArg]; `action` is null for a
   * token that looks like an option but matches nothing.
   */
  _parseOptional(argString) {
    // 1. empty string -> positional.
    if (argString === '') return null;
    // 2. does not start with a prefix char -> positional.
    if (!this.prefixChars.includes(argString[0])) return null;
    // 3. exact match.
    if (this._optionStringActions.has(argString)) {
      return [this._optionStringActions.get(argString), argString, null, null];
    }
    // 4. a lone prefix char ('-') -> positional.
    if (argString.length === 1) return null;
    // 5. '--opt=value' where '--opt' is known.
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      if (this._optionStringActions.has(optionString)) {
        return [this._optionStringActions.get(optionString), optionString, '=', argString.slice(eq + 1)];
      }
    }
    // 6. abbreviations / single-dash clusters.
    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const options = optionTuples.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }
    // 7. negative numbers are values unless an option is spelled like one.
    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !this._hasNegativeNumberOptionals) return null;
    // 8. anything containing a space was meant to be a value.
    if (argString.includes(' ')) return null;
    // 9. an option, but an unknown one.
    return [null, argString, null, null];
  }

  /** CPython `_get_option_tuples`: every interpretation of an abbreviated option. */
  _getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;

    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
      // Long options are only ever split at '='; the rest is a prefix to match.
      const eq = optionString.indexOf('=');
      const optionPrefix = eq === -1 ? optionString : optionString.slice(0, eq);
      const sep = eq === -1 ? null : '=';
      const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);
      for (const [known, action] of this._optionStringActions) {
        if (known.startsWith(optionPrefix)) result.push([action, known, sep, explicitArg]);
      }
    } else if (chars.includes(optionString[0])) {
      // Single-dash: either '-x' with 'yz' glued on, or an abbreviation of a
      // longer single-dash option.
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [known, action] of this._optionStringActions) {
        if (known === shortOptionPrefix) result.push([action, known, '', shortExplicitArg]);
        else if (known.startsWith(optionString)) result.push([action, known, null, null]);
      }
    }

    return result;
  }

  /** CPython `_match_argument`: how many following tokens this action takes. */
  _matchArgument(action, argStringsPattern) {
    const match = new RegExp(`^${getNargsPattern(action)}`).exec(argStringsPattern);
    if (match === null) {
      throw new ArgumentError(action, nargsErrorMessage(action.nargs));
    }
    return match[1].length;
  }

  /**
   * CPython `_match_arguments_partial`: try the positionals as a whole, then
   * progressively fewer of them, and return the token count each one gets.
   */
  _matchArgumentsPartial(actions, argStringsPattern) {
    for (let i = actions.length; i > 0; i -= 1) {
      const pattern = actions.slice(0, i).map(getNargsPattern).join('');
      const match = new RegExp(`^${pattern}`).exec(argStringsPattern);
      if (match !== null) return match.slice(1).map((group) => group.length);
    }
    return [];
  }

  /** CPython `_get_values`: turn the matched tokens into the stored value. */
  _getValues(action, argStrings) {
    const strings = [...argStrings];
    // `arg_strings.remove('--')`: a positional swallowing the separator drops it.
    const separator = strings.indexOf('--');
    if (separator !== -1) strings.splice(separator, 1);

    // A single token for a one-value action produces a scalar; every other
    // shape (including the empty list of a nargs=0 action) produces a list.
    if (strings.length === 1 && (action.nargs === null || action.nargs === '?')) {
      const value = this._getValue(action, strings[0]);
      this._checkValue(action, value);
      return value;
    }
    const values = strings.map((string) => this._getValue(action, string));
    for (const value of values) this._checkValue(action, value);
    return values;
  }

  /** CPython `_get_value`: run `type=` and translate its failures. */
  _getValue(action, argString) {
    const typeFunc = action.type ?? identity;
    try {
      return typeFunc(argString);
    } catch (err) {
      // CPython catches ArgumentTypeError, TypeError and ValueError here and
      // names the type via `action.type.__name__` -- hence `int`/`str` being
      // declared as named functions in types.mjs.
      if (err instanceof ArgumentTypeError || err instanceof PyValueError
          || err instanceof PyTypeError) {
        throw new ArgumentError(action, `invalid ${typeFunc.name} value: ${reprStr(argString)}`);
      }
      throw err;
    }
  }

  /** CPython `_check_value`: enforce `choices=`. */
  _checkValue(action, value) {
    if (action.choices !== null && !action.choices.includes(value)) {
      const choices = action.choices.map(reprValue).join(', ');
      throw new ArgumentError(
        action,
        `invalid choice: ${reprValue(value)} (choose from ${choices})`,
      );
    }
  }

  /* --------------------------------------------------------------- output --- */

  /** CPython: HelpFormatter width is `shutil.get_terminal_size().columns - 2`. */
  _width() {
    return getTerminalColumns() - 2;
  }

  /** CPython `format_usage`: the usage block, with its single trailing newline. */
  formatUsage() {
    return `${formatUsage({ prog: this.prog, actions: this._actions, width: this._width() })}\n`;
  }

  /** CPython `format_help`: usage block, then one section per action group. */
  formatHelp() {
    return formatHelp({
      prog: this.prog,
      actions: this._actions,
      groups: this._actionGroups,
      width: this._width(),
    });
  }

  printUsage(toStderr = false) {
    const text = this.formatUsage();
    if (toStderr) writeStderr(text);
    else writeStdout(text);
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** CPython `exit`: optional message to stderr, then SystemExit. Never returns. */
  exitWith(status = 0, message = null) {
    if (message) writeStderr(message);
    exit(status);
  }

  /** CPython `error`: usage to stderr, one unwrapped error line, exit code 2. */
  error(message) {
    this.printUsage(true);
    this.exitWith(2, `${this.prog}: error: ${message}\n`);
  }
}

export { Action, StoreAction, HelpAction, SUPPRESS };

