// Public surface of the argparse subset, so that the entry file can read like
// Python's `import argparse` / `from argparse import ArgumentParser`.
//
// Python's `argparse` module exposes the parser, the sentinel SUPPRESS, the
// Action classes and the two exception types; the `int`/`str` type callables
// stand in for the Python builtins that `type=` receives.

export { ArgumentParser } from './parser.mjs';
export { Action, StoreAction, HelpAction, SUPPRESS } from './actions.mjs';
export { ArgumentError, ArgumentTypeError, getActionName } from './errors.mjs';
export { int, str } from './types.mjs';
